#include <iostream>
#include <vector>
#include <array>
#include <limits>
#include <string>
// 공백으로 나눈 토큰 전체를 검사합니다. 숫자 사이의 붙은 부호는 허용하지 않습니다.
template <typename T>
bool ReadInteger(T& result, long long low, long long high) {
    std::string token;
    if (!(std::cin >> token)) return false;
    std::size_t pos = 0;
    bool negative = false;
    if (token[pos] == '+' || token[pos] == '-') {
        negative = token[pos] == '-';
        if (++pos == token.size()) return false;
    }
    const long long bound = (-low > high) ? -low : high;
    long long magnitude = 0;
    for (; pos < token.size(); ++pos) {
        if (token[pos] < '0' || token[pos] > '9') return false;
        const int digit = token[pos] - '0';
        if (digit > bound || magnitude > (bound - digit) / 10) return false;
        magnitude = magnitude * 10 + digit;
    }
    const long long value = negative ? -magnitude : magnitude;
    if (value < low || value > high) return false;
    result = static_cast<T>(value);
    return true;
}
int main(){
    int rows, cols;
    if(!ReadInteger(rows,1,25)||!ReadInteger(cols,1,25)) return 1;
    std::vector<std::vector<long long> > p(rows+1,std::vector<long long>(cols+1,0));
    for(int i=0;i<rows;++i) for(int j=0;j<cols;++j){
        long long x; if(!ReadInteger(x,-1000000,1000000)) return 1;
        // 위와 왼쪽을 더하고 겹친 부분을 한 번 뺍니다.
        p[i+1][j+1]=x+p[i][j+1]+p[i+1][j]-p[i][j];
    }
    std::string extra; if(std::cin>>extra) return 1;
    long long best=std::numeric_limits<long long>::lowest();
    std::array<int,4> answer={{0,0,0,0}};
    for(int top=0;top<rows;++top) for(int left=0;left<cols;++left)
      for(int bottom=top;bottom<rows;++bottom) for(int right=left;right<cols;++right){
        const long long sum=p[bottom+1][right+1]-p[top][right+1]-p[bottom+1][left]+p[top][left];
        const std::array<int,4> key={{top,left,bottom,right}};
        // 빈 영역은 후보로 만들지 않습니다. 동률이면 좌표 튜플을 비교합니다.
        if(sum>best || (sum==best && key<answer)){best=sum;answer=key;}
      }
    std::cout<<best;
    for(int k=0;k<4;++k) std::cout<<' '<<answer[k];
    std::cout<<'\n';
}
